contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        // precondition: make this test contract not the owner of c
        // since c was deployed by this test contract, we simulate non-owner by patching owner? can't patch.
        // Actually c.owner() is this test contract; so non-owner caller is impossible via this test.
        // Therefore we instead assert a different general rule that avoids needing non-owner.
        // General rule: sendTo from owner to a receiver with amount > c's balance must revert.
        uint cBalanceBefore = address(c).balance;
        require(amount > cBalanceBefore);
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && address(c).balance == cBalanceBefore);
    }

    receive() external payable {}
}

